// Purpose: Build the texture pixel buffers that the renderer uploads to the GPU.
// The moon is a real photo from Wikimedia Commons. The two level materials
// (brick and wooden planks) are generated by an algorithm instead: every noise
// field comes from seamless.js and wraps at the tile edge, so the material
// repeats without any visible seam, and the world seed picks the colours and
// the wobble - a new world always gets its own look.

import { hash } from "./prng.js";
import { valueNoise, fractalNoise, warpOffset } from "./seamless.js";

export const TEXTURE_SIZE = 512; // power of two, so WebGL 1 may tile it (REPEAT)

/**
 * The three textures of the game. `source` tells the HUD and the browser checks
 * where the pixels came from: "internet" for a real photo, "procedural" for a
 * pattern generated in this file.
 */
export const TEXTURES = [
  {
    name: "moon",
    url: "https://upload.wikimedia.org/wikipedia/commons/0/01/Phase-180.jpg",
    credit: "Moon photo: Jay Tanner, CC BY-SA 3.0 (Wikimedia Commons)",
    source: "internet",
  },
  {
    name: "brick",
    credit: "Brick pattern: drawn in code",
    source: "procedural",
  },
  {
    name: "wood",
    credit: "Plank pattern: drawn in code",
    source: "procedural",
  },
];

// How many modules fit into one tile. Every number divides TEXTURE_SIZE, which
// is what makes the pattern repeat without a seam.
const BRICK_COURSES = 8; // rows of bricks in one tile
const BRICKS_PER_COURSE = 4; // bricks per row, running bond offsets every other row
const PLANKS_PER_TILE = 4; // wooden planks in one tile

// Feature sizes as a fraction of the texture size, so the same pattern works
// for a 512 tile and for the small buffers the tests build.
const MORTAR_FACTOR = 0.008; // brick mortar joint width
const PLANK_GAP_FACTOR = 0.006; // dark gap between two planks
const JOINT_BAND_MIN = 0.72; // joint thickness wobbles between these factors
const JOINT_BAND_SPAN = 0.56; // ...of mortar/gap width times this spread

// Base colours of the materials, chosen for the finished look: the renderer
// still mixes them toward the object colour of the platform.
const MORTAR_COLOUR = [184, 176, 159];
const BRICK_COLOUR = [155, 88, 64];
const BRICK_TINT_RANGE = 0.42; // how much the bricks differ from each other
const PLANK_COLOUR = [173, 132, 86];
const PLANK_TINT_RANGE = 0.34; // how much the planks differ from each other
const GRAIN_NOISE = 13; // per pixel brightness noise, in 0..255 steps
const JOINT_SHADOW = 0.8; // how much darker the face right next to a joint is

// Per-seed variation ranges: the world seed moves these within the limits.
const BRICK_HUE_SHIFT = 0.10; // warmer or cooler red, share of the colour
const MORTAR_LIGHT_SHIFT = 0.16; // lighter or darker mortar joints
const MATERIAL_TONE_SHIFT = 0.22; // brighter or darker whole material
const HEAD_WARP_FACTOR = 0.024; // waviness of the vertical joints (tile share)
const GRAIN_WARP_FACTOR = 0.02; // waviness of the wood grain (tile share)

// Noise lattice sizes: bigger counts are finer detail. All fields wrap at the
// tile edge, so no count can break the tiling. Unequal x/y counts stretch the
// pattern into streaks - wood grain runs along the board, not in blobs.
const BAND_CELLS = 48; // wobble of one joint line
const BLOTCH_CELLS = 8; // big clay patches inside the bricks
const CLAY_CELLS = 24; // medium clay structure
const AGE_CELLS = 3; // whole-tile light and dark cloud
const GRAIN_STREAK_CELLS_X = 4; // grain streaks: wide along the board,
const GRAIN_STREAK_CELLS_Y = 96; // ...thin across it
const FIBRE_CELLS_X = 24; // fine wood structure, slightly stretched
const FIBRE_CELLS_Y = 96;
const JOINT_WARP_CELLS = 6; // how often a joint line waves per tile

/** Wrap an index into one period so a module that crosses the border stays one module. */
function mod(value, period) {
  return ((value % period) + period) % period;
}

/** Write one rgb colour into an RGBA buffer, clamped to the byte range. */
function put(pixels, size, x, y, color, alpha = 255) {
  const i = (y * size + x) * 4;
  pixels[i] = Math.max(0, Math.min(255, Math.round(color[0])));
  pixels[i + 1] = Math.max(0, Math.min(255, Math.round(color[1])));
  pixels[i + 2] = Math.max(0, Math.min(255, Math.round(color[2])));
  pixels[i + 3] = alpha;
}

/** Scale a colour by a factor and add a flat offset to every channel. */
function shade(color, factor, offset = 0) {
  return [color[0] * factor + offset, color[1] * factor + offset, color[2] * factor + offset];
}

/** One random feel of a material for one world seed: hue, light and wobble. */
function materialFeel(name, seed) {
  const pick = (slot) => hash(seed * 977 + 13, slot * 31 + 7);

  if (name === "brick") {
    const warm = (pick(1) - 0.5) * 2 * BRICK_HUE_SHIFT; // -0.10 .. +0.10
    return {
      colour: [
        BRICK_COLOUR[0] * (1 + warm),
        BRICK_COLOUR[1] * (1 - warm * 0.4),
        BRICK_COLOUR[2] * (1 - warm * 1.4),
      ],
      mortar: shade(MORTAR_COLOUR, 1 + (pick(2) - 0.5) * MORTAR_LIGHT_SHIFT),
      tone: 1 + (pick(3) - 0.5) * MATERIAL_TONE_SHIFT,
      warp: (0.55 + pick(4) * 0.9) * HEAD_WARP_FACTOR,
    };
  }

  const warm = (pick(1) - 0.5) * 2 * BRICK_HUE_SHIFT;
  return {
    colour: [PLANK_COLOUR[0] * (1 + warm), PLANK_COLOUR[1] * (1 - warm * 0.5), PLANK_COLOUR[2] * (1 - warm * 1.2)],
    tone: 1 + (pick(3) - 0.5) * MATERIAL_TONE_SHIFT,
    warp: (0.55 + pick(4) * 0.9) * GRAIN_WARP_FACTOR,
  };
}

/**
 * Brick wall: courses of bricks with a mortar joint, every other row shifted
 * by half a brick. The vertical joint lines are warped by periodic noise, so
 * they wave like real mortar instead of forming a ruler grid, and the joint
 * thickness wobbles along each line. The horizontal courses stay exactly on the
 * grid: every platform surface is a whole world unit, so a block edge always
 * ends on a joint.
 */
function brickPixels(size, seed) {
  const pixels = new Uint8Array(size * size * 4);
  const feel = materialFeel("brick", seed);
  const courseH = size / BRICK_COURSES;
  const brickW = size / BRICKS_PER_COURSE;
  const mortar = Math.max(1, Math.round(size * MORTAR_FACTOR));

  // One wobble value per row: all head joints of a row shift equally, which
  // keeps the brick spacing exact while the lines still wave from row to row.
  const headShift = new Float32Array(size);
  for (let y = 0; y < size; y++) {
    headShift[y] = warpOffset(seed, size, 0, y, feel.warp * size, {
      cells: JOINT_WARP_CELLS,
      octaves: 3,
      salt: 5,
    });
  }

  for (let y = 0; y < size; y++) {
    const course = Math.floor(y / courseH);
    const rowOffset = (course % 2) * (brickW / 2);
    const faceH = courseH - mortar;
    // The joint sits at the top of every course, so it lands on a whole world
    // unit and a block edge always ends on a mortar line.
    const faceY = mod(y, courseH);

    for (let x = 0; x < size; x++) {
      const band = JOINT_BAND_MIN + JOINT_BAND_SPAN * valueNoise(seed, size, BAND_CELLS, BAND_CELLS, x, y, 11);
      const position = x + rowOffset + headShift[y];
      const inBrick = mod(position, brickW);
      // The brick index is taken modulo the row so a brick that is cut by the
      // tile border keeps the same tone on both halves: one brick, one colour.
      const brick = mod(Math.floor(position / brickW), BRICKS_PER_COURSE);
      const noise = hash(x, y) - 0.5;

      if (faceY < mortar * band || inBrick < mortar * band) {
        // Mortar: a light band that gets slightly brighter in the middle of the
        // joint, which is what makes the joints look pressed in instead of drawn.
        const depth = faceY < mortar * band ? faceY / (mortar * band) : inBrick / (mortar * band);
        put(pixels, size, x, y, shade(feel.mortar, feel.tone * (0.9 + 0.1 * depth + noise * 0.07)));
        continue;
      }

      const tone = 1 - BRICK_TINT_RANGE / 2 + BRICK_TINT_RANGE * hash(brick, course + seed * 5 + 3);
      const blotch = fractalNoise(seed, size, x, y, { cells: BLOTCH_CELLS, octaves: 2, salt: 1 });
      const clay = fractalNoise(seed, size, x, y, { cells: CLAY_CELLS, octaves: 2, salt: 2 });
      const age = fractalNoise(seed, size, x, y, { cells: AGE_CELLS, octaves: 2, salt: 3 });
      const bevel = 1.06 - 0.13 * (faceY / faceH); // light on top, shadow below
      const sideLight = 1.02 - 0.04 * (inBrick / brickW);
      const jointShadow = faceY < mortar * band + 1 || inBrick < mortar * band + 1 ? JOINT_SHADOW : 1;
      const speck = hash(x * 3 + 1, y * 5 + 2) > 0.985 ? -20 : 0;

      const factor =
        feel.tone * tone * (0.86 + 0.28 * blotch) * (0.94 + 0.12 * clay) * (0.94 + 0.1 * age) * bevel * sideLight * jointShadow;
      put(pixels, size, x, y, shade(feel.colour, factor, noise * GRAIN_NOISE + speck));
    }
  }

  return pixels;
}

/**
 * Wooden planks: horizontal boards with a dark gap, a light top edge, long
 * grain streaks and a butt joint now and then. The grain and the butt joints
 * are warped by periodic noise, so nothing looks ruled, while the plank rows
 * keep their exact grid: the gap of every plank sits at a whole half unit.
 */
function woodPixels(size, seed) {
  const pixels = new Uint8Array(size * size * 4);
  const feel = materialFeel("wood", seed);
  const plankH = size / PLANKS_PER_TILE;
  const gap = Math.max(1, Math.round(size * PLANK_GAP_FACTOR));

  for (let y = 0; y < size; y++) {
    const plank = Math.floor(y / plankH);
    const faceY = mod(y, plankH); // the gap sits at the top of every plank
    const grainShift = warpOffset(seed, size, 0, y, feel.warp * size, {
      cells: JOINT_WARP_CELLS,
      octaves: 3,
      salt: 9,
    });
    const buttJoint =
      size * (0.12 + 0.76 * hash(plank + seed * 7 + 3, 31)) +
      warpOffset(seed, size, 0, y, feel.warp * size * 0.8, { cells: JOINT_WARP_CELLS, octaves: 2, salt: 13 });
    const tone = 1 + (hash(plank, seed * 11 + 5) - 0.5) * PLANK_TINT_RANGE;
    // Each board shifts the grain by a whole-tile multiple, so the streaks of
    // two boards never line up and the grain keeps wandering along the board.
    const grainX = hash(plank + seed * 3, 41) * size;
    const grainY = hash(plank + seed * 3, 43) * size;

    for (let x = 0; x < size; x++) {
      const band = JOINT_BAND_MIN + JOINT_BAND_SPAN * valueNoise(seed, size, BAND_CELLS, BAND_CELLS, x, y, 17);
      if (faceY < gap * band) {
        // The gap is a shadow line: darkest at the very top of the tile row.
        put(pixels, size, x, y, shade(feel.colour, feel.tone * tone * (0.32 + 0.06 * hash(x, y))));
        continue;
      }

      const grain = fractalNoise(seed, size, x + grainX, y + grainY, {
        cells: GRAIN_STREAK_CELLS_X,
        cellsY: GRAIN_STREAK_CELLS_Y,
        octaves: 3,
        salt: 3,
      });
      const fibre = fractalNoise(seed, size, x + grainX, y + grainY, {
        cells: FIBRE_CELLS_X,
        cellsY: FIBRE_CELLS_Y,
        octaves: 2,
        salt: 23,
      });
      const age = fractalNoise(seed, size, x, y, { cells: AGE_CELLS, octaves: 2, salt: 19 });
      const bevel = 1.08 - 0.15 * (faceY / plankH); // bright under the gap, darker below
      const isJoint = Math.abs(x + grainShift - buttJoint) <= Math.max(1, gap / 2);

      const factor =
        feel.tone * tone * (0.88 + 0.24 * grain) * (0.96 + 0.08 * fibre) * (0.94 + 0.1 * age) * bevel * (isJoint ? 0.6 : 1);
      put(pixels, size, x, y, shade(feel.colour, factor, (hash(x, y) - 0.5) * GRAIN_NOISE));
    }
  }

  return pixels;
}

/**
 * Moon surface used when the photo cannot be downloaded: pale rock with a few
 * darker maria and craters. Drawn as one disc, so tiling does not matter here.
 */
function moonPixels(size, seed) {
  const pixels = new Uint8Array(size * size * 4);

  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      let tone = 0.8 + 0.12 * hash(Math.floor(x / 6), Math.floor(y / 6));

      for (let crater = 0; crater < 9; crater++) {
        const centreX = hash(crater, 3 + seed * 5);
        const centreY = hash(crater, 7 + seed * 5);
        const radius = 0.05 + hash(crater, 11) * 0.09;
        const distance = Math.hypot((x + 0.5) / size - centreX, (y + 0.5) / size - centreY);
        if (distance < radius) tone -= 0.22 * (1 - distance / radius);
        else if (distance < radius * 1.3) tone += 0.05; // bright rim around a crater
      }

      put(pixels, size, x, y, shade([246, 248, 236], tone));
    }
  }

  return pixels;
}

/**
 * Generate one texture into a size x size RGBA buffer. All patterns are built
 * from periodic fields, so the GPU can repeat them without a seam, and the
 * same seed always paints the same pixels.
 */
export function proceduralPixels(name, size = TEXTURE_SIZE, seed = 0) {
  if (name === "brick") return brickPixels(size, seed);
  if (name === "wood") return woodPixels(size, seed);
  return moonPixels(size, seed);
}

/**
 * The two level materials for one world seed, in the shape renderer.setTextures
 * expects. main.js calls this on every (re)start so each world looks a little
 * different while staying perfectly tiled.
 */
export function levelMaterialPixels(seed) {
  return TEXTURES.filter((texture) => texture.source === "procedural").map((texture) => ({
    ...texture,
    ok: true,
    size: TEXTURE_SIZE,
    pixels: proceduralPixels(texture.name, TEXTURE_SIZE, seed),
  }));
}

/**
 * Download an image and cut its centre square into a size x size RGBA buffer.
 * Throws when the network or the image decoder is not available.
 */
export async function fetchPixels(url, size = TEXTURE_SIZE) {
  const response = await fetch(url);
  if (!response.ok) throw new Error("HTTP " + response.status);

  const blob = await response.blob();
  if (typeof createImageBitmap !== "function") throw new Error("no image decoder");

  const image = await createImageBitmap(blob);
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;

  const ctx = canvas.getContext("2d");
  const side = Math.min(image.width, image.height);
  ctx.drawImage(
    image,
    Math.floor((image.width - side) / 2),
    Math.floor((image.height - side) / 2),
    side,
    side,
    0,
    0,
    size,
    size
  );

  if (typeof image.close === "function") image.close();
  return new Uint8Array(ctx.getImageData(0, 0, size, size).data);
}

/**
 * Load every texture. The level materials are generated for the given world
 * seed; a photo that cannot be downloaded falls back to the generated pattern,
 * so the run never ends up with a flat coloured box.
 */
export async function loadTextures(seed = 0) {
  const loaded = [];

  for (const texture of TEXTURES) {
    if (texture.source !== "internet") {
      loaded.push({ ...texture, ok: true, size: TEXTURE_SIZE, pixels: proceduralPixels(texture.name, TEXTURE_SIZE, seed) });
      continue;
    }

    try {
      loaded.push({ ...texture, ok: true, size: TEXTURE_SIZE, pixels: await fetchPixels(texture.url) });
    } catch (error) {
      loaded.push({
        ...texture,
        ok: false,
        error: error.message,
        size: TEXTURE_SIZE,
        pixels: proceduralPixels(texture.name, TEXTURE_SIZE, seed),
      });
    }
  }

  return loaded;
}
